def balance_workload(tasks, capacity):
    # tasks: list of task weights, capacity: max per server
    servers = [0, 0, 0]
    assignments = [[], [], []]

    for task in tasks:
        # Find the server with the most remaining space
        server_idx = servers.index(min(servers))
        if servers[server_idx] + task <= capacity:
