To flatten a nested list without hitting recursion limits, an iterative approach using a stack is the most robust method. Here is the implementation:

def flatten_list(nested_list):
    stack = [iter(nested_list)]
    result = []
    while stack:
        try:
            item = next(stack[-1])
            if isinstance(item, list):
                stack.append(iter(item))
            else:
                result.append(item)
        except StopIteration:
            stack.pop()
    return result

