To achieve O(1) complexity, we combine a dictionary (for O(1) key-based lookup) and a doubly linked list (to track access order in O(1) time). When an item is accessed, it is moved to the head of the list; when the capacity is exceeded, the tail is removed.

```python
class Node:
    def __init__(self, key, value):
        self.key, self.value = key, value
        self.prev = self.next = None

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.head, self.tail = Node(0, 0), Node(0, 0)
        self.head.next, self.tail.prev = self.tail, self.head

    def get(self, key):
        if key in self.cache:
            node = self.cache[key]
            self._remove(node)
            self._add(node)
            return node.value
        return -1

    def put(self, key, value):
        if key in self.cache: self._remove(self.cache[key])
        node = Node(key, value)
        self.cache[key] = node
        self._add(node)
        if len(self.cache) > self.capacity:
            lru = self.head.next
            self._remove(lru)
            del self.cache[lru.key]

    def _add(self, node):
        p = self.tail.prev
        p.next, node.prev, node.next, self.tail.prev = node, p, self.tail, node

    def _remove(self, node):
        p, n = node.prev, node.next
        p.next, n.prev = n, p
```

