def fetch_with_retry(request_func, retries=3, backoff_factor=1.0):
    """
    Executes a function with exponential backoff on failure.
    """
    for i in range(retries):
        try:
            return request_func()
        except Exception as e:
            if i == retries - 1:
                raise e
            sleep_time = (backoff_factor * (2 ** i)) + (random.uniform(0, 1))
