def ethical_decision_engine(options, weights):
    """
    Evaluates options based on a dictionary of ethical weights.
    weights: {'transparency': 0.4, 'privacy': 0.3, 'accuracy': 0.3}
    """
    best_option = None
    max_score = -float('inf')

    for option in options:
