To implement a basic fairness constraint, we can use a demographic parity check. This function ensures that the positive prediction rate is similar across different groups.

def check_fairness(predictions, group_labels, threshold=0.1):
    groups = set(group_labels)
    rates = {}
    for g in groups:
        group_preds = [p for p, l in zip(predictions, group_labels) if l == g]
        rates[g] = sum(group_preds) / len(group_preds)

    max_rate = max(rates.values())
    min_rate = min(rates.values())

    return (max_rate - min_rate) <= threshold
